from ...base.client import BaseClient


class SurveysMethods(BaseClient):
    """
    Методы группы 'Опросы про' из https://im-docs.corp.mail.ru/
    """

    async def rapi_survey_begin(self, survey_id: str):
        """
        Начать прохождение/пройти еще раз - удаляет всю историю голосования
        пользователя,
        начинает фиксировать прохождение Опрос Про как первый раз.
        """
        return await self.post(
            "rapi/survey/begin",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"surveyId": survey_id},
            },
        )

    async def rapi_survey_vote(self, survey_id: str, question_id: str, value):
        """
        Проголосовать/переголосовать (покрывает и revoke)
        по данному опросу на конкретный вопрос.
        """
        return await self.post(
            "rapi/survey/vote",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "surveyId": survey_id,
                    "questionId": question_id,
                    "value": value,
                },
            },
        )

    async def rapi_survey_get(self, survey_id: str):
        """
        Получение всей имеющейся информации об опросе.
        """
        return await self.post(
            "rapi/survey/get",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"surveyId": survey_id},
            },
        )
